-- Times are UTC. 09:00 UTC ≈ 3:00 AM Mountain (standard); adjust for DST if you care about the exact minute.
select cron.schedule('daily-ideas', '0 9 * * *', $$ select net.http_post(url := current_setting('app.functions_url') || '/daily-ideas', headers := jsonb_build_object('Authorization', 'Bearer ' || current_setting('app.service_key')), body := '{"all":true}') $$);
select cron.schedule('lantern-today', '5 11 * * *', $$ select net.http_post(url := current_setting('app.functions_url') || '/lantern-today', headers := jsonb_build_object('Authorization', 'Bearer ' || current_setting('app.service_key')), body := '{"study":true}') $$);
select cron.schedule('plaid-refresh', '0 */6 * * *', $$ select net.http_post(url := current_setting('app.functions_url') || '/plaid-webhook', headers := jsonb_build_object('Authorization', 'Bearer ' || current_setting('app.service_key')), body := '{"webhook_code":"CRON_REFRESH"}') $$);
select cron.schedule('morning-summary', '0 13 * * *', $$ select net.http_post(url := current_setting('app.functions_url') || '/voice', headers := jsonb_build_object('Authorization', 'Bearer ' || current_setting('app.service_key')), body := '{"action":"push_morning_summary"}') $$);
select cron.schedule('interest-plan', '0 10 1 * *', $$ select net.http_post(url := current_setting('app.functions_url') || '/interest-plan', headers := jsonb_build_object('Authorization', 'Bearer ' || current_setting('app.service_key')), body := '{"all":true}') $$);
